-- Run this in Snowsight on QIAPQJI-YM84445 as JBILEKTRIAL (ACCOUNTADMIN)

-- Key-pair service user for CI tests
CREATE USER JBILEKTRIAL_CI_KP
  TYPE = SERVICE
  RSA_PUBLIC_KEY = ''
  DEFAULT_ROLE = SYSADMIN;
GRANT ROLE SYSADMIN TO USER JBILEKTRIAL_CI_KP;

-- OIDC service user for CI tests
CREATE USER JBILEKTRIAL_CI_OIDC
  TYPE = SERVICE
  WORKLOAD_IDENTITY = (
    TYPE = OIDC
    ISSUER = 'https://token.actions.githubusercontent.com'
    SUBJECT = 'repo:sfc-gh-jbilek/snowflake-actions-test:ref:refs/heads/main'
  )
  DEFAULT_ROLE = SYSADMIN;
GRANT ROLE SYSADMIN TO USER JBILEKTRIAL_CI_OIDC;
